compiled.rows:
function anonymous(formatMinutes,pendingTimeAccountDuties,timeAccountActual,timeAccountBalance,timeAccountCaption,timeCreditLabel,formatMonthTitle,SHIFT_TYPE_LABELS,SHIFT_TYPE_COLORS,DEFAULT_SHIFT_SYMBOLS,report,pending,palette,analysis,creditsAvailable,timeCredits,caption,item,month,testMonths,element,fragment
) {
"use strict";
const creditById = new Map(timeCredits.map((line) => [line.shiftId, line]));
const groups = analysis.groups ??
    analysis.items.map((item) => ({
        ...item,
        key: item.type,
        title: SHIFT_TYPE_LABELS[item.type],
        color: SHIFT_TYPE_COLORS[item.type],
        symbol: DEFAULT_SHIFT_SYMBOLS[item.type],
        types: [item.type],
        entries: [],
    }));
const rows = [
    ...groups.map((group) => {
        const labels = [
            ...new Set(group.entries.flatMap((entry) => {
                const line = creditById.get(entry.id);
                return line ? [timeCreditLabel(line)] : [];
            })),
        ];
        return {
            ...group,
            total: false,
            hours: !creditsAvailable && group.types.some((type) => type === "VACATION" || type === "SICK")
                ? "Nicht verfügbar"
                : formatMinutes(group.minutes) + " h",
            subtitle: labels.length === 1
                ? labels[0]
                : labels.length
                    ? "Unterschiedlicher Ausgleich"
                    : undefined,
        };
    }),
    {
        key: "TOTAL",
        title: "Gesamt",
        count: analysis.totalCount,
        hours: formatMinutes(analysis.totalMinutes) + " h",
        color: "",
        symbol: "",
        entries: [],
        subtitle: undefined,
        total: true,
    },
];
return rows;

}

